const pets=[['raccoon','小浣熊'],['penguin','小企鵝'],['rabbit','小兔子'],['fox','小狐狸'],['bear','小熊'],['cat','小貓'],['shiba','柴犬'],['capybara','水豚'],['owl','小貓頭鷹'],['otter','小水獺']];
const key='credit-pet-island-v1',money=n=>new Intl.NumberFormat('zh-TW',{style:'currency',currency:'TWD',maximumFractionDigits:0}).format(n||0),iso=d=>d.toISOString().slice(0,10),now=new Date(),month=now.toISOString().slice(0,7);
let state=JSON.parse(localStorage.getItem(key)||'null')||seed();
function seed(){const y=now.getFullYear(),m=String(now.getMonth()+1).padStart(2,'0'),past=new Date(y,now.getMonth()-1,18);return{cards:[{id:'demo1',bank:'國泰世華',cardName:'Cube 卡',last4:'1234',statementDay:5,dueDay:20,petType:'raccoon',petName:'回饋寶',stage:'adult',xp:130,coins:65,active:true,note:'日常消費',bills:[{id:'b1',month:`${y}-${m}`,amount:12580,paid:false,note:''},{id:'b0',month:past.toISOString().slice(0,7),amount:8560,paid:true,paidAt:past.toISOString().slice(0,10),method:'轉帳',note:''}]},{id:'demo2',bank:'玉山銀行',cardName:'U Bear',last4:'5678',statementDay:10,dueDay:25,petType:'penguin',petName:'旅遊球',stage:'juvenile',xp:40,coins:18,active:true,note:'旅遊與網購',bills:[{id:'b2',month:`${y}-${m}`,amount:3240,paid:true,paidAt:iso(now),method:'自動扣繳',note:''}]}]}}
function save(){localStorage.setItem(key,JSON.stringify(state));render()}
function pet(c){return pets.find(p=>p[0]===c.petType)?.[1]||'寵物'} function pos(type){let i=pets.findIndex(p=>p[0]===type);return `${(i%5)*25}% ${i>4?'100%':'0%'}`}
function dueDate(card,bill){let [y,m]=bill.month.split('-').map(Number),d=Math.min(card.dueDay,new Date(y,m,0).getDate());return new Date(y,m-1,d,12)}
function status(card,bill){if(bill.paid)return['已繳款','paid'];let days=Math.ceil((dueDate(card,bill)-new Date(now.getFullYear(),now.getMonth(),now.getDate()))/86400000);if(days<0)return['請確認是否已繳款','urgent'];if(days===0)return['今天到期！','urgent'];if(days<=3)return[`剩 ${days} 天要繳款`,'urgent'];if(days<=7)return[`還有 ${days} 天要繳款`,'soon'];return[`還有 ${days} 天要繳款`,'normal']}
function currentBill(c){return c.bills.find(b=>b.month===month)}
function cardHTML(c,album=false){let b=currentBill(c),s=b?status(c,b):['等待帳單','normal'];return `<article class="pet-card status-${s[1]}"><div class="pet-art" style="background-position:${pos(c.petType)}"></div><div class="card-body"><div class="card-top"><div><h3>${c.petName} <small>｜${c.stage==='adult'?'成年':'幼年'}${pet(c)}</small></h3><p class="subtle">${c.bank}・${c.cardName}・末四碼 ${c.last4}</p></div><span class="pill ${s[1]}">${album?'旅行中':s[0]}</span></div>${album?`<div class="amount">陪伴紀錄</div><p class="due">${c.bills.length} 筆帳單・${c.coins} 枚金幣<br>旅行日：${c.travelDate||'—'}</p><div class="card-actions"><button onclick="detail('${c.id}')">查看回憶帳本</button><button class="pay" onclick="returnIsland('${c.id}')">邀請回小島</button></div>`:b?`<div class="amount">${money(b.amount)}</div><p class="due">結帳日：每月 ${c.statementDay} 日<br>繳款截止日：${dueDate(c,b).toLocaleDateString('zh-TW',{month:'numeric',day:'numeric'})}</p><div class="card-actions">${b.paid?'<button onclick="detail(\''+c.id+'\')">查看帳本</button>':`<button class="pay" onclick="openPay('${c.id}','${b.id}')">去繳款</button><button onclick="detail('${c.id}')">查看帳本</button>`}<button onclick="openTravel('${c.id}')">去旅行</button></div>`:`<div class="amount">尚未輸入</div><p class="due">結帳日：每月 ${c.statementDay} 日<br>繳款截止日：每月 ${c.dueDay} 日</p><div class="card-actions"><button class="pay" onclick="openBill('${c.id}')">新增本月帳單</button><button onclick="detail('${c.id}')">查看帳本</button><button onclick="openTravel('${c.id}')">去旅行</button></div>`}</div></article>`}
function render(){let active=state.cards.filter(c=>c.active),travel=state.cards.filter(c=>!c.active),due=active.map(c=>[c,currentBill(c)]).filter(x=>x[1]&&!x[1].paid);document.querySelector('#totalDue').textContent=money(due.reduce((a,x)=>a+x[1].amount,0));document.querySelector('#activeDue').textContent=`${due.length} 張`;let nearest=due.sort((a,b)=>dueDate(a[0],a[1])-dueDate(b[0],b[1]))[0];document.querySelector('#closestDue').textContent=nearest?dueDate(nearest[0],nearest[1]).toLocaleDateString('zh-TW',{month:'numeric',day:'numeric'}):'全部完成';document.querySelector('#coinTotal').textContent=`${state.cards.reduce((a,c)=>a+c.coins,0)} 枚`;document.querySelector('#heroMessage').textContent=due.length?`還有 ${due.length} 張卡等待照顧，先看看最近要到期的夥伴。`:'本月帳單都已處理完成，小島的夥伴正在開心休息！';document.querySelector('#cardGrid').innerHTML=active.map(c=>cardHTML(c)).join('');document.querySelector('#albumGrid').innerHTML=travel.map(c=>cardHTML(c,true)).join('');document.querySelector('#islandEmpty').classList.toggle('hidden',!!active.length);document.querySelector('#albumEmpty').classList.toggle('hidden',!!travel.length);document.querySelector('#albumCount').textContent=travel.length}
function open(id){document.querySelector(id).showModal()}function setupDays(){for(let id of ['statementDay','dueDay'])document.querySelector('#'+id).innerHTML=Array.from({length:31},(_,i)=>`<option value="${i+1}">每月 ${i+1} 日</option>`).join('')}
function setupPets(){document.querySelector('#petPicker').innerHTML=pets.map(([id,name])=>`<button type="button" class="pet-option ${id==='raccoon'?'selected':''}" data-pet="${id}" style="background-position:${pos(id)}"><span>${name}</span></button>`).join('');document.querySelectorAll('.pet-option').forEach(b=>b.onclick=()=>{document.querySelectorAll('.pet-option').forEach(x=>x.classList.remove('selected'));b.classList.add('selected');document.querySelector('#petType').value=b.dataset.pet})}
function openBill(id){document.querySelector('#billForm').reset();document.querySelector('#billCardId').value=id;document.querySelector('#billMonth').value=month;document.querySelector('#billTitle').textContent=`幫${find(id).petName}整理帳本`;open('#billDialog')}
function openPay(cid,bid){let c=find(cid),b=c.bills.find(x=>x.id===bid);document.querySelector('#payForm').reset();document.querySelector('#payCardId').value=cid;document.querySelector('#payBillId').value=bid;document.querySelector('#paidAt').value=iso(now);document.querySelector('#payTitle').textContent=`幫${c.petName}完成繳款`;document.querySelector('#paySummary').textContent=`本期帳單 ${money(b.amount)}・截止日 ${dueDate(c,b).toLocaleDateString('zh-TW')}`;open('#payDialog')}
function openTravel(id){let c=find(id);document.querySelector('#travelCardId').value=id;document.querySelector('#travelTitle').textContent=`要讓「${c.petName}」去旅行嗎？`;open('#travelDialog')}function find(id){return state.cards.find(c=>c.id===id)}
function detail(id){let c=find(id),bills=[...c.bills].sort((a,b)=>b.month.localeCompare(a.month));document.querySelector('#detailContent').innerHTML=`<div class="detail-head"><div class="pet-art" style="background-position:${pos(c.petType)}"></div><div><p class="eyebrow">${c.active?'信用卡小島':'回憶帳本'}</p><h2>${c.petName}的${c.active?'帳本':'回憶帳本'}</h2><p class="subtle">${c.bank}・${c.cardName}・末四碼 ${c.last4}<br>等級：${c.stage==='adult'?'成年夥伴':'幼年夥伴'}・${c.coins} 枚金幣</p></div></div><table class="history"><thead><tr><th>年月</th><th>帳單金額</th><th>截止日</th><th>狀態</th><th>繳款日期</th></tr></thead><tbody>${bills.map(b=>`<tr><td>${b.month}</td><td>${money(b.amount)}</td><td>${dueDate(c,b).toLocaleDateString('zh-TW',{month:'numeric',day:'numeric'})}</td><td>${b.paid?'已繳':'待繳'}</td><td>${b.paidAt||'—'}</td></tr>`).join('')||'<tr><td colspan="5">還沒有帳單紀錄</td></tr>'}</tbody></table>`;open('#detailDialog')}
function returnIsland(id){let c=find(id);c.active=true;delete c.travelDate;save();toast(`歡迎 ${c.petName} 回到小島！`)}function toast(t){let e=document.querySelector('#toast');e.textContent=t;e.classList.add('show');setTimeout(()=>e.classList.remove('show'),2800)}
document.querySelectorAll('.add-trigger,#addCardBtn,#quickAdd').forEach(x=>x.onclick=()=>{document.querySelector('#cardForm').reset();document.querySelector('#petType').value='raccoon';document.querySelectorAll('.pet-option').forEach(x=>x.classList.toggle('selected',x.dataset.pet==='raccoon'));open('#cardDialog')});document.querySelectorAll('[data-view]').forEach(x=>x.onclick=()=>{let v=x.dataset.view;document.querySelector('#islandView').classList.toggle('hidden',v!=='island');document.querySelector('#albumView').classList.toggle('hidden',v!=='album');document.querySelectorAll('.tab').forEach(t=>t.classList.toggle('active',t.dataset.view===v))});
document.querySelector('#cardForm').addEventListener('submit',e=>{e.preventDefault();let g=id=>document.querySelector('#'+id).value,stateCard={id:crypto.randomUUID(),bank:g('bank'),cardName:g('cardName'),last4:g('last4'),statementDay:+g('statementDay'),dueDay:+g('dueDay'),petType:g('petType'),petName:g('petName'),stage:'juvenile',xp:0,coins:0,active:true,note:g('note'),bills:[]};state.cards.push(stateCard);document.querySelector('#cardDialog').close();save();toast(`${stateCard.petName} 已經入住信用卡小島！`)});
document.querySelector('#billForm').addEventListener('submit',e=>{e.preventDefault();let c=find(document.querySelector('#billCardId').value),m=document.querySelector('#billMonth').value,a=+document.querySelector('#billAmount').value;if(c.bills.some(b=>b.month===m)){toast('這個月份已經有帳單，請先在帳本查看。');return}c.bills.push({id:crypto.randomUUID(),month:m,amount:a,paid:false,note:document.querySelector('#billNote').value});c.xp+=10;document.querySelector('#billDialog').close();save();toast(`${c.petName} 獲得 10 點整理帳本經驗值！`)});
document.querySelector('#payForm').addEventListener('submit',e=>{e.preventDefault();let c=find(document.querySelector('#payCardId').value),b=c.bills.find(x=>x.id===document.querySelector('#payBillId').value);b.paid=true;b.paidAt=document.querySelector('#paidAt').value;b.method=document.querySelector('#paymentMethod').value;b.note=document.querySelector('#payNote').value;let ontime=new Date(b.paidAt+'T12:00')<=dueDate(c,b);c.xp+=30;c.coins+=ontime?15:5;if(c.stage==='juvenile'&&c.xp>=90)c.stage='adult';document.querySelector('#payDialog').close();save();toast(ontime?`${c.petName} 開心地獲得 15 枚金幣！`:`已記錄繳款，${c.petName} 會繼續陪伴你。`)});
document.querySelector('#travelForm').addEventListener('submit',e=>{e.preventDefault();let c=find(document.querySelector('#travelCardId').value);c.active=false;c.travelDate=iso(now);document.querySelector('#travelDialog').close();save();toast(`${c.petName} 已經住進回憶相簿。`)});document.querySelector('#resetBtn').onclick=()=>{if(confirm('要回復成示範資料嗎？您新增的資料會被清除。')){state=seed();save();toast('已回復試玩資料。')}};setupDays();setupPets();render();
